 }catch(Exception e){r.status="FAILED_NO_PROMOTION";r.error=e.ToString();Debug.LogException(e);}finally{alternate?.Dispose();foreach(var b in buffers)b.Dispose();foreach(var q in owned.AsEnumerable().Reverse())if(q!=null)UnityEngine.Object.DestroyImmediate(q);File.WriteAllText(Environment.GetEnvironmentVariable("LF_NATIVE67_REPORT"),JsonUtility.ToJson(r,true));Debug.Log("AGENT_RESULT "+r.status);EditorApplication.Exit(exit);}}
